insert into rules (slug, rule_topic_id, scope_type, governing_body_id, applies_to) values ('ncaa-nil-allowed', (select id from rule_topics where slug = 'nil-allowed'), 'governing_body', (select id from governing_bodies where slug = 'ncaa'), 'college');
insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, effective_date, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'ncaa-nil-allowed'), 1, 'yes_with_conditions', 'Yes. Division I athletes may be paid for the use of their name, image and likeness in third-party deals.', 'NIL cannot be payment for playing or for athletic achievement.', 'NCAA Division I Bylaws 22.01.1 and 22.1.2', '2025-07-01', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text', 'YES', 'Yes. Division I athletes can be paid by third parties for their NIL.');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-nil-allowed' and v.is_current), (select id from sources where slug = 'ncaa-d1-manual-2026-27'), 'Bylaws 22.01.1, 22.1.2', 'An individual may receive compensation for the use of the individual’s name, image and likeness, which may be secured or compensated based, in whole or in part, on athletics skill or reputation. ... An individual may permit the use of the individual’s name, image, likeness in noninstitutional name, image and likeness activities and receive compensation for such activities.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into verification_events (entity_type, entity_id, status, method, verified_on, verified_by, notes) values ('rule_version', (select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-nil-allowed' and v.is_current), 'VERIFIED_TO_OFFICIAL_SOURCE', 'automated_fetch', '2026-10-03', 'Claude (automated source research)', 'Full page text read from the official site by Claude. Not a human review.');
