insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status, trust_state, review_method) values ((select id from rules where slug = 'ncaa-prohibited-categories'), 1, 'not_addressed', 'We found no list of prohibited product categories for NIL deals in NCAA Bylaw Article 22. NCAA sports wagering rules outside Article 22 were not reviewed, so do not read this as permission.', 'NCAA Division I Manual 2026-27, Article 22 (no provision found)', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text');
