insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status, trust_state, review_method) values ((select id from rules where slug = 'ncaa-recruiting'), 1, 'no', 'No. Pay to attend or compete for a specific school is pay-for-play and is not allowed.', 'NCAA NIL page, "What''s allowed vs. not allowed"', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text');
