insert into rules (slug, rule_topic_id, scope_type, governing_body_id, applies_to) values ('ncaa-transfers', (select id from rule_topics where slug = 'transfers'), 'governing_body', (select id from governing_bodies where slug = 'ncaa'), 'college');
insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status, trust_state, review_method) values ((select id from rules where slug = 'ncaa-transfers'), 1, 'yes_with_conditions', 'Four-year transfers must report deals of $600 or more signed from the date they entered the Transfer Portal. A deal that was already cleared and stays in place does not need to be resubmitted.', 'NCAA Division I Bylaw 22.2.2.5.2', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-transfers' and v.is_current), (select id from sources where slug = 'ncaa-d1-manual-2026-27'), 'Bylaw 22.2.2.5.2', 'Prospective four-year college transfers shall report all noninstitutional name, image, and likeness contracts or payment terms with compensation of $600 or more that have been executed from the date in which the student-athlete’s name was officially entered into the NCAA Transfer Portal. A transfer who has previously reported a deal that will remain in place upon transfer shall not be required to resubmit the deal if it has been cleared by the CSC.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into verification_events (entity_type, entity_id, status, method, verified_on, verified_by, notes) values ('rule_version', (select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-transfers' and v.is_current), 'VERIFIED_TO_OFFICIAL_SOURCE', 'automated_fetch', '2026-10-03', 'Claude (automated source research)', 'Full page text read from the official site by Claude. Not a human review.');
insert into rules (slug, rule_topic_id, scope_type, governing_body_id, applies_to) values ('ncaa-prospects-reporting', (select id from rule_topics where slug = 'prospects-reporting'), 'governing_body', (select id from governing_bodies where slug = 'ncaa'), 'both');
insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status, trust_state, review_method) values ((select id from rules where slug = 'ncaa-prospects-reporting'), 1, 'yes', 'Yes. An athlete enrolling at a Division I school must report third-party deals of $600 or more made since the first day of junior year of high school (or July 1, 2025, if later). The deadline is 14 days after enrolling full time or before the team''s first game, whichever comes first.', 'NCAA Division I Bylaws 22.2.2.5.1 and 22.2.2.5.3', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-prospects-reporting' and v.is_current), (select id from sources where slug = 'ncaa-d1-manual-2026-27'), 'Bylaws 22.2.2.5.1, 22.2.2.5.3', 'An incoming prospective student-athlete must report noninstitutional name, image and likeness contracts or payment terms not later than either 14 days after initial full-time enrollment at a Division I institution, or prior to the institution’s first scheduled contest against outside competition in the individual''s sport, whichever occurs first.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-prospects-reporting' and v.is_current), (select id from sources where slug = 'ncaa-nil-page'), 'High school prospects planning to play Division I', 'Report threshold: all third-party NIL deals worth $600 or more since July 1, 2025 or starting your junior year of high school, whichever is later', 'machine_extracted', '2026-10-03', 'Claude (automated source research)');
insert into verification_events (entity_type, entity_id, status, method, verified_on, verified_by, notes) values ('rule_version', (select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-prospects-reporting' and v.is_current), 'VERIFIED_TO_OFFICIAL_SOURCE', 'automated_fetch', '2026-10-03', 'Claude (automated source research)', 'Full page text read from the official site by Claude. Not a human review.');
insert into rules (slug, rule_topic_id, scope_type, governing_body_id, applies_to) values ('csc-international', (select id from rule_topics where slug = 'international-athletes'), 'governing_body', (select id from governing_bodies where slug = 'college-sports-commission'), 'college');
insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status, trust_state, review_method) values ((select id from rules where slug = 'csc-international'), 1, 'yes_with_conditions', 'International athletes must report deals of $600 or more like every Division I athlete, but whether a deal is legal for them can depend on immigration rules. The College Sports Commission tells them to consult their school before going ahead.', 'CSC FAQ, "Are international student-athletes required to report third-party NIL deals?"', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'csc-international' and v.is_current), (select id from sources where slug = 'csc-faq'), 'International student-athletes', 'All Division I student-athletes are required to report their third-party NIL deals at or above $600 in aggregate in NIL Go. However, the legality of such deals may vary depending on factors including state and federal laws and immigration regulations. Student-athletes should reach out to their institution for guidance and consult with them before proceeding with any third-party NIL deals.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into verification_events (entity_type, entity_id, status, method, verified_on, verified_by, notes) values ('rule_version', (select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'csc-international' and v.is_current), 'VERIFIED_TO_OFFICIAL_SOURCE', 'automated_fetch', '2026-10-03', 'Claude (automated source research)', 'Full page text read from the official site by Claude. Not a human review.');
insert into rules (slug, rule_topic_id, scope_type, institution_id, applies_to) values ('uf-nil-allowed', (select id from rule_topics where slug = 'nil-allowed'), 'institution', (select id from institutions where slug = 'university-of-florida'), 'college');
insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'uf-nil-allowed'), 1, 'yes_with_conditions', 'Yes. UF tells its athletes they have full rights to profit from their NIL, and that every paid deal must be a real exchange: you provide a service or promotion and get paid for it.', 'UF, Overview of Gators NIL', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text', 'YES', 'Yes. It has to be a real exchange: you do something for the brand and get paid for it.');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'uf-nil-allowed' and v.is_current), (select id from sources where slug = 'uf-nil-overview'), 'Opening section', 'Good news – as a Florida Gator you have full rights to profit from your Name, Image, and Likeness (NIL) as long as you follow a few common-sense rules. ... every paid NIL deal must be a ''quid pro quo'' arrangement (you provide services or promotion, and in return you get paid)', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
