insert into rules (slug, rule_topic_id, scope_type, institution_id, applies_to) values ('shs-event-footage', (select id from rule_topics where slug = 'event-footage'), 'institution', (select id from institutions where slug = 'seminole-high-school-sanford'), 'high_school');
insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, nil_specific) values ((select id from rules where slug = 'shs-event-footage'), 1, 'only_with_approval', 'Only with written approval. Seminole High School''s media credential terms prohibit secondary or commercial use of pictures, audio or film of its athletics events made by a credential holder, including advertising and sales promotion, without prior specific written approval of Seminole High School Athletics. Separately, FHSAA Bylaw 9.10.4.3 bars referring to a member school event or game in NIL activity.', 'These terms bind credentialed media. The page does not address footage shot by families or the athlete.', 'Seminole High School Athletics, Media Credential Request terms', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text', FALSE);
