insert into rules (slug, rule_topic_id, scope_type, institution_id, applies_to) values ('fsu-school-logos-marks', (select id from rule_topics where slug = 'school-logos-marks'), 'institution', (select id from institutions where slug = 'florida-state-university'), 'college');
insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'fsu-school-logos-marks'), 1, 'only_with_approval', 'FSU says NIL deals without university trademarks need no prior approval. Anything that uses FSU logos or athletic marks, or implies university affiliation, must go through the Office of Trademark Licensing and be cleared by FSU''s Global Partnerships team. FSU says its corporate partners signed through Florida State Global Partnerships / Legends can use FSU logos and marks in deals with athletes. FSU says athletes need prior written approval to use FSU trademarks and logos in NIL. A written agreement must come from Florida State Global Partnerships or the FSU Office of Trademark Licensing.', 'FSU also says NIL items must follow brand standards and be made by licensed vendors. Applies to official FSU corporate partners only. Page is undated. The document is marked ''Last Updated 2/2/2024'', before the House settlement. It is still linked from FSU''s current NIL page as ''Use of University Marks & Group Licensing''.', 'FSU The Brand page, NIL tab; The Florida State Factor page; FSU NIL: Use of University Marks, page 1', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text', 'CHECK_FIRST', 'FSU logos in NIL need licensing approval first.');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fsu-school-logos-marks' and v.is_current), (select id from sources where slug = 'fsu-s4'), 'NIL', 'Student-athletes may participate in NIL opportunities that do not involve university trademarks without prior approval.', 'machine_raw_text', '2026-10-04', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fsu-school-logos-marks' and v.is_current), (select id from sources where slug = 'fsu-s4'), 'NIL', 'any merchandise, endorsements or promotions that include FSU logos, athletic marks or imply university affiliation must go through the Office of Trademark Licensing and receive additional clearance from FSU’s Global Partnerships team.', 'machine_raw_text', '2026-10-04', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fsu-school-logos-marks' and v.is_current), (select id from sources where slug = 'fsu-s4'), 'Sponsorship', 'Any commercial use of FSU Athletic marks - including sponsorship, advertising, endorsements, or NIL campaigns - must be coordinated through this office.', 'machine_raw_text', '2026-10-04', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fsu-school-logos-marks' and v.is_current), (select id from sources where slug = 'fsu-s2'), 'Connect with student-athletes with local & national brands', 'These partners have the ability to use FSU logos and marks in deals with student athletes.', 'machine_raw_text', '2026-10-04', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fsu-school-logos-marks' and v.is_current), (select id from sources where slug = 'fsu-t1'), 'Use of University Marks/Images', 'Student-athletes must receive prior written approval and follow University licensing procedures and brand guidelines to use intellectual property from the Office of Trademark Licensing.', 'machine_raw_text', '2026-10-04', 'Claude (automated source research)');
