insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'fsu-own-merchandise'), 1, 'only_with_approval', 'FSU says athletes who opt in to group licensing agreements can earn royalties from officially licensed merchandise that pairs their NIL with FSU marks. FSU says any merchandise with FSU trademarks or logos must be made by a University licensee and approved through FSU''s Office of Trademark Licensing.', 'Page is undated and cites 2023 figures. The document is marked ''Last Updated 2/2/2024'', before the House settlement. It is still linked from FSU''s current NIL page as ''Use of University Marks & Group Licensing''. Athlete merchandise with no FSU marks is not covered by this sentence.', 'The Florida State Factor page, group licensing; FSU NIL: Use of University Marks, page 1', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text', 'CHECK_FIRST', 'Merch with FSU marks must come from a licensee.');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fsu-own-merchandise' and v.is_current), (select id from sources where slug = 'fsu-s2'), 'Opportunities', 'By opting into group licensing agreements, student-athletes are able to earn royalties from the sale of jerseys, t-shirts, and other officially licensed merchandise featuring their NIL with Florida State marks.', 'machine_raw_text', '2026-10-04', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fsu-own-merchandise' and v.is_current), (select id from sources where slug = 'fsu-t1'), 'How am I able to use University marks on merchandise?', 'needs to be manufactured by a University licensee and be approved through FSU’s Office of Trademark Licensing', 'machine_raw_text', '2026-10-04', 'Claude (automated source research)');
