insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'fsu-school-facilities'), 1, 'only_with_approval', 'FSU says using campus facilities or grounds for NIL needs written authorization from FSU. Commercial filming or photography also needs approval from the Office of University Communications. FSU says to ask several weeks ahead through the address on the official page.', 'The document is marked ''Last Updated 2/2/2024'', before the House settlement. It is still linked from FSU''s current NIL page as ''Use of University Marks & Group Licensing''. FSU says insurance, rental fees and a location agreement may be required.', 'FSU NIL: Use of University Marks, pages 1 and 2', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text', 'CHECK_FIRST', 'Campus shoots need written FSU authorization.');
