insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'fsu-event-footage'), 1, 'only_with_approval', 'FSU says photos shared with athletes on INFLCR are for building a personal brand and may not be monetized without written pre-approval. FSU points sponsors to Getty Images, Catapult or Imagn to license photos or footage for NIL.', 'The document is marked ''Last Updated 2/2/2024'', before the House settlement. It is still linked from FSU''s current NIL page as ''Use of University Marks & Group Licensing''.', 'FSU NIL: Use of University Marks, page 2', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text', 'CHECK_FIRST', 'Team photos and footage must be licensed first.');
