insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'fsu-agents'), 1, 'only_with_approval', 'FSU says agents and representatives must register with FSU before contacting an FSU athlete about NIL, and must submit the Agent Registration Form every year. After signing an athlete, the agent must send FSU Compliance an Athlete Representation Disclosure Form. FSU says an athlete, parent or guardian may contact an agent. FSU advises the athlete to tell the Athletics Compliance Office before the first contact. Agents who reach out to athletes must notify the Compliance Office before the first contact.', 'From FSU''s agent procedures revised February 2026. Agents not yet registered must finish within seven business days of first contact. From FSU''s agent procedures revised February 2026. The wording ''It is advised'' is softer than the FSU Compliance web page, which makes notice a condition.', 'FSU Compliance SOP: Student-Athlete Agent (Revised 02/2026), items 1, 2, 5 and 7; FSU Compliance SOP: Student-Athlete Agent (Revised 02/2026), items 3 and 4', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text', 'CHECK_FIRST', 'Agents must register with FSU every year.');
