insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, review_note, quick_status, short_answer) values ((select id from rules where slug = 'ucf-collectives'), 1, 'not_addressed', 'UCF said in 2024 that the work of its former official collective, The Kingdom, would move into UCF''s own ChargeOn Fund. UCF''s current pages point donors to the Competitive Success Fund instead of a collective.', 'UCF does not publish a rule for athletes about working with outside collectives.', 'UCF Athletics director letter, November 18, 2024', 'researched', 'PUBLIC_POLICY_NOT_LOCATED', 'raw_source_text', 'Not located in the public sources reviewed as of October 4, 2026.', 'NOT_PUBLICLY_SPECIFIED', 'UCF moved its collective''s work in-house.');
