insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'fiu-disclosure-required'), 1, 'yes', 'FIU says athletes must disclose a proposed deal through the INFLCR app before entering the agreement. The handbook also describes reporting outside deals in NIL Go.', 'What the school adds: the INFLCR app and the before-signing timing. The NIL Go text in the handbook repeats the national process.', 'FIU 2026-2027 Student-Athlete Handbook, NIL section', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text', 'YES', 'Disclose in the INFLCR app before you sign.');
