insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'fiu-deal-review'), 1, 'yes_with_conditions', 'FIU says the Senior Associate AD for Compliance reviews NIL disclosures. Deals over $10,000 get an extra review by the Athletics Director. A denied deal''s conflicts must be fixed within 10 days.', 'The handbook sentence about a five business day review is garbled in the source and is not quoted as a rule.', 'FIU Policy 910.001 and FIU 2026-2027 Student-Athlete Handbook', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text', 'DEPENDS', 'FIU reviews deals. Big ones get a second review.');
