insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'fiu-agents'), 1, 'yes_with_conditions', 'FIU requires agents and financial advisors to register with the athletic department before any contact with an athlete. Athletes are told to send them to the Athletics Compliance Office. FIU says a meeting with a registered agent can be arranged if it is on campus with a compliance staff member present. FIU says the registration forms are on its athletics site.', 'The section is about agents in general and does not single out NIL-only representatives. The forms were not located on the Compliance page. The same section still has an older rule against agreeing to agent representation for marketing athletic ability, which does not mention NIL.', 'FIU 2026-2027 Student-Athlete Handbook, Agents and Financial Advisors', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text', 'CHECK_FIRST', 'Agents must register with FIU first.');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fiu-agents' and v.is_current), (select id from sources where slug = 'fiu-s2'), 'Agents and Financial Advisors, handbook pages 100 to 101', 'FIU policy requires all agents, financial advisors and/or any associates employed by the aforementioned, to register with the athletic department before making any contact with a student-athlete.', 'machine_raw_text', '2026-10-04', 'Claude (automated source research)');
