insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, review_note, quick_status, short_answer) values ((select id from rules where slug = 'bcu-collectives'), 1, 'yes_with_conditions', 'Bethune-Cookman Athletics announced the Hail Maroon and Gold Collective in August 2024 as a partnership with Student Athlete NIL (SANIL). B-CU says SANIL is not officially affiliated with the athletics department but is acknowledged by it.', 'This release is from August 2024, before the House settlement. The collective website linked from the athletics menu did not load on October 3, 2026, so current status is unknown. Published before the July 2025 rule changes or undated. Confirm with the school that it still applies.', 'Hail Maroon and Gold Collective Unveiled (Aug. 1, 2024)', 'needs_verification', 'PENDING_INSTITUTION_CONFIRMATION', 'raw_source_text', 'The school published this before the July 2025 rule changes, or on an undated page. It has not been confirmed as current.', 'CHECK_FIRST', 'B-CU acknowledged a third-party collective in 2024. Current status unknown.');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'bcu-collectives' and v.is_current), (select id from sources where slug = 'bcu-s4'), 'Final paragraph', 'SANIL is not officially affiliated with Bethune-Cookman Athletics but is acknowledged by the athletics department and will operate within NCAA, Southwestern Athletic Conference (SWAC), and Florida state parameters', 'machine_raw_text', '2026-10-04', 'Claude (automated source research)');
