insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, review_note, quick_status, short_answer) values ((select id from rules where slug = 'ju-disclosure-required'), 1, 'yes', 'JU says athletes must disclose all NIL opportunities in a timely manner and give JU athletics copies of any signed agreements. JU says INFLCR is the tool for disclosure.', 'JU says this is not an approval process. The page ties the duty to Florida Statute 1006.74, which is from before the House settlement. This page dates from 2022, before the House settlement. Confirm with JU compliance that it still applies.', 'JU Name, Image and Likeness page, NIL Overview and Guidelines', 'needs_verification', 'PENDING_INSTITUTION_CONFIRMATION', 'raw_source_text', 'The school published this before the July 2025 rule changes, or on an undated page. It has not been confirmed as current.', 'CHECK_FIRST', 'Disclose every NIL deal to JU athletics and send signed copies.');
